        print(f"Source data figure 5.xlsx/{sheet}: {len(rows)} rows, {len(rows[0]) if rows else 0} cols")
        if rows:
            print(f"  Header: {rows[0][:5]}")
            if len(rows) > 1:
                print(f"  Row 1: {rows[1][:5]}")
    except Exception as e:
        print(f"Error reading {sheet}: {e}")

# Check Source data Fig.S14.xlsx, as Figure S14J is referenced for the original model accuracy
